-- =====================================================================
-- 118. Senado: composición (XV Legislatura) en las tablas de sql/91
--
-- GENERADO por scripts/senado-composicion.py con los ficheros de datos
-- abiertos del Senado descargados a mano el 02/11/2026: senado.es devuelve 403
-- (Akamai) a GovTalent desde Vercel, así que no hay sync automático hasta
-- que el Senado dé acceso. No editar a mano: regenerar.
--
-- 71 senadores en activo (Cámara disuelta el 06-10-2026: siguen
-- la Diputación Permanente y quienes conservan el escaño) y 7 grupos.
-- Quien no figure en el hemiciclo queda inactivo, sin borrarse. Las
-- comisiones no se cargan: el fichero no trae sus miembros.
-- Se puede ejecutar más de una vez.
-- =====================================================================

on conflict (id) do update set legislatura = excluded.legislatura, nombre = excluded.nombre, sigla = excluded.sigla, n_diputados = excluded.n_diputados, color = excluded.color, fecha_constitucion = excluded.fecha_constitucion, id_fuente = excluded.id_fuente, activo = true, fuente = excluded.fuente, synced_at = now();

update public.ccaa_grupos set activo = false, n_diputados = 0 where parlamento = 'senado' and id not in ('senado:gpp', 'senado:gps', 'senado:gperb', 'senado:gpplu', 'senado:gpv', 'senado:gpic', 'senado:gpmx');

on conflict (id) do update set legislatura = excluded.legislatura, nombre = excluded.nombre, apellidos_nombre = excluded.apellidos_nombre, grupo_id = excluded.grupo_id, sexo = excluded.sexo, circunscripcion = excluded.circunscripcion, email = coalesce(excluded.email, ccaa_diputados.email), twitter = coalesce(excluded.twitter, ccaa_diputados.twitter), datos = excluded.datos, id_fuente = excluded.id_fuente, fecha_alta = excluded.fecha_alta, activo = true, fuente = excluded.fuente, fuente_fecha = now(), updated_at = now();

update public.ccaa_diputados set activo = false, updated_at = now() where parlamento = 'senado' and activo and id not in ('senado:pedro-manuel-rollan-ojeda', 'senado:javier-ignacio-maroto-aranzabal', 'senado:eva-ortiz-vilella', 'senado:maria-mar-blanco-garrido', 'senado:concepcion-andreu-rodriguez', 'senado:angel-luis-gonzalez-munoz', 'senado:maria-jose-garcia-pelayo-jurado', 'senado:gerardo-camps-devesa', 'senado:maria-del-rocio-divar-conde', 'senado:jose-antonio-monago-terraza', 'senado:jose-manuel-barreiro-fernandez', 'senado:maria-salom-coll', 'senado:francisco-javier-arenas-bocanegra', 'senado:alicia-garcia-rodriguez', 'senado:antonio-silvan-rodriguez', 'senado:luisa-fernanda-rudi-ubeda', 'senado:pio-garcia-escudero-marquez', 'senado:vicente-tirado-ochoa', 'senado:eduard-pujol-bonell', 'senado:nerea-ahedo-ceza', 'senado:juan-espadas-cejas', 'senado:alfonso-gil-invernon', 'senado:maria-jesus-montero-cuadrado', 'senado:cesar-alejandro-mogo-zaro', 'senado:maria-fernandez-alvarez', 'senado:maria-amparo-marco-gual', 'senado:inmaculada-sanchez-roca', 'senado:antonio-poveda-zapata', 'senado:javier-anton-cacho', 'senado:jose-manuel-franco-pardo', 'senado:carmen-torralba-valiente', 'senado:sara-bailac-ardanuy', 'senado:pedro-manuel-sangines-gutierrez', 'senado:javier-campoy-monreal', 'senado:pilar-milagros-rojo-noguera', 'senado:fernando-martinez-maillo-toribio', 'senado:juan-manuel-avila-gutierrez', 'senado:paloma-martin-martin', 'senado:alejo-joaquin-miranda-de-larra-arnaiz', 'senado:nidia-maria-arevalo-gomez', 'senado:alfonso-carlos-serrano-sanchez-capuchino', 'senado:rosa-maria-romero-sanchez', 'senado:francisco-martin-bernabe-perez', 'senado:jose-angel-alonso-perez', 'senado:juan-jose-matari-saez', 'senado:carlos-yecora-roca', 'senado:jose-manuel-rey-varela', 'senado:paloma-ines-sanz-jeronimo', 'senado:ana-maria-beltran-villalba', 'senado:angel-pelayo-gordillo-moreno', 'senado:maria-mar-caballero-martinez', 'senado:gorka-elejabarrieta-diaz', 'senado:miguel-gracia-f